```scala
import java.io._
import scala.collection.mutable.ListBuffer
import scala.util.control.Exception._

val products = List("Apple", "Milk", "Car", "Dog")

def categorize(product: String): String = product match {
  case "Apple" | "Milk" => "essential"
  case _ => "non-essential"
}

val essential = new ListBuffer[String]()
val non_essential = new ListBuffer[String]()

for (product <- products) {
  categorize(product) match {
    case "essential"    => essential += product
    case "non-essential" => non_essential += product
  }
}

val result = s""""essential", "${essential.mkString(",")}"\n"non-essential", "${non_essential.mkString(",")}""""

val file = new File("result.csv")
val bwResult = allCatch.either {
  val bw = new BufferedWriter(new FileWriter(file))
  try {
    bw.write(result)
    bw.close()
    "Categorization done and saved as CSV file."
  } catch {
    case e: FileNotFoundException => s"File error: ${e.getMessage}"
    case e: IOException           => s"IO error: ${e.getMessage}"
  }
}

bwResult match {
  case Right(res) => println(res)
  case Left(ex)   => println(s"An error occurred: ${ex.getMessage}")
}
```

