```swift
struct ContentView: View {
    @State private var selectedTab: Int = 0
    private let scrollViews: [[String]] = [
        ["Item 0", "Item 1", "Item 2"],
        ["Item 3", "Item 4", "Item 5"],
        ["Item 6", "Item 7", "Item 8"]
    ]

    var body: some View {
        TabView(selection: $selectedTab) {
            ForEach(scrollViews.indices, id: \.self) { index in
                ScrollView {
                    VStack {
                        ForEach(scrollViews[index].indices, id: \.self) { itemIndex in
                            Text("Item \(scrollViews[index][itemIndex])")
                        }
                    }
                }
                .padding()
